# edit_engineimport streamlit as stimport jsonfrom datetime import datetimedef run_edit_workflow(PATHS, get_all_spec_files, extract_itw_display_name):    """    Edit Engine: Handles the synchronization and protection of existing Logic Maps.    """    st.title("Logic Map Files")    st.header("Edit Logic Maps")        spec_files = get_all_spec_files()        if not spec_files:        st.warning("No logic maps found in the /spec directory.")    else:        # Map display names to actual file paths        file_map = {extract_itw_display_name(f.name): f for f in spec_files}        selected_itw = st.selectbox("Select ITW_ID", options=[""] + sorted(list(file_map.keys())))                if selected_itw:            target_path = file_map[selected_itw]            try:                with open(target_path, "r", encoding="utf-8") as f:                    data = json.load(f)            except Exception as e:                st.error(f"Error reading logic file: {e}")                data = {}                        # Handle both list-wrapped and direct dictionary JSONs            content = data[0] if isinstance(data, list) else data            updated_content = {}                        # Table Header            h1, h2 = st.columns([2, 5])            with h1: st.markdown('<p class="header-label">Framework Field</p>', unsafe_allow_html=True)            with h2: st.markdown('<p class="header-label">Deterministic Value</p>', unsafe_allow_html=True)            # Field-by-Field Editor            for k, v in content.items():                c1, c2 = st.columns([2, 5])                with c1:                     # Keys are disabled to protect the Logic RFC schema                    st.text_input("K", value=k, disabled=True, key=f"k_{selected_itw}_{k}", label_visibility="collapsed")                with c2:                     # Protect core protocol fields from accidental editing                    is_prot = k.lower() in ["itw_id", "version", "original_author", "file_type"]                    updated_content[k] = st.text_input("V", value=str(v), disabled=is_prot, key=f"v_{selected_itw}_{k}", label_visibility="collapsed")                        if st.button("Save Changes"):                # Update audit timestamp for DIOPTRAS tracking                updated_content["last_updated"] = datetime.now().strftime("%Y-%m-%d %H:%M:%S")                with open(target_path, "w", encoding="utf-8") as f:                    json.dump(updated_content, f, indent=4)                st.success(f"Logic for {selected_itw} Synchronized.")                st.rerun()